_DEFAULT_KEY = "default"


@dataclass(frozen=True)
class PhaseTable[T]:
    """A setting that may be a scalar, per-preset, or per-phase-and-preset.

    Three accepted YAML forms::

        nodes: 4                                  # one value for every job
        nodes: {170M: 1, 400M: 4}                 # per preset
        nodes: {default: {...}, bridge: {...}}    # per phase, then per preset

    The presence of a ``default`` key is what distinguishes the third form from the second.
    """

    name: str
    scalar: T | None
    tables: dict[str, dict[str, T]]

    @classmethod
    def from_value(cls, value: object, *, name: str) -> PhaseTable[T]:
        """Build a table from any of the three accepted forms."""
        if not isinstance(value, Mapping):
            return cls(name=name, scalar=value, tables={})  # ty: ignore[invalid-argument-type]
        if _DEFAULT_KEY in value:
            tables = {
                str(phase): {str(preset): entry for preset, entry in dict(sub).items()}
                for phase, sub in value.items()
                if isinstance(sub, Mapping)
            }
            if not tables:
                raise ValueError(f"{name}.default must map presets to values")
            return cls(name=name, scalar=None, tables=tables)
        return cls(
            name=name,
            scalar=None,
            tables={_DEFAULT_KEY: {str(preset): entry for preset, entry in value.items()}},
        )

    def resolve(self, *, phase: str | None, preset: str | None) -> T:
        """Resolve the value for one (phase, preset) pair.

        Raises:
            KeyError: If no entry covers ``preset``.
        """
        if self.scalar is not None:
            return self.scalar
        table = self.tables.get(phase or "", self.tables.get(_DEFAULT_KEY, {}))
        if preset is not None and preset in table:
            return table[preset]
        fallback = self.tables.get(_DEFAULT_KEY, {})
        if preset is not None and preset in fallback:
            return fallback[preset]
        # A phase-keyed entry with no preset dimension (e.g. analyze) stores its single value
        # under the phase name itself.
        if phase is not None and phase in self.tables:
            single = self.tables[phase]
            if len(single) == 1:
                return next(iter(single.values()))
        raise KeyError(f"{self.name} has no entry for phase={phase!r} preset={preset!r}")

